"""Create original vector teaching schematics; no textbook/publisher artwork copied."""
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
DEST=ROOT/'assets/chapter-06'
HEAD='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 420" role="img"><rect width="960" height="420" rx="16" fill="#f5f9fc"/><defs><marker id="red" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#c34b49"/></marker><marker id="blue" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#24678c"/></marker></defs><g font-family="Arial,sans-serif" fill="#173b50">'''
TAIL='</g></svg>'


def generate():
    DEST.mkdir(exist_ok=True)
    yee=HEAD+'''<text x="35" y="37" font-size="23">Yee cell: electric edges, magnetic faces</text><g fill="none" stroke="#91aaba" stroke-width="2"><path d="M90 145 L290 145 L380 90 L180 90 Z M90 145 V330 H290 V145 M290 330 L380 275 V90 M90 330 L180 275 H380 M180 90 V275"/></g><path d="M110 330 H220" stroke="#c34b49" stroke-width="5" marker-end="url(#red)"/><path d="M305 321 L365 284" stroke="#c34b49" stroke-width="5" marker-end="url(#red)"/><path d="M90 310 V205" stroke="#c34b49" stroke-width="5" marker-end="url(#red)"/><path d="M335 210 H430" stroke="#24678c" stroke-width="5" marker-end="url(#blue)"/><path d="M235 117 V55" stroke="#24678c" stroke-width="5" marker-end="url(#blue)"/><path d="M190 237 L255 197" stroke="#24678c" stroke-width="5" marker-end="url(#blue)"/><text x="150" y="358" fill="#c34b49" font-size="20">Ex</text><text x="328" y="321" fill="#c34b49" font-size="20">Ey</text><text x="48" y="245" fill="#c34b49" font-size="20">Ez</text><text x="435" y="216" fill="#24678c" font-size="20">Hx</text><text x="260" y="195" fill="#24678c" font-size="20">Hy</text><text x="250" y="80" fill="#24678c" font-size="20">Hz</text><text x="480" y="95" font-size="22">Space staggering</text><text x="480" y="132" font-size="19">E: centers of primal edges</text><text x="480" y="165" font-size="19">H: centers of primal faces</text><text x="480" y="225" font-size="22">Time staggering</text><path d="M490 280 H905" stroke="#91aaba" stroke-width="2"/><circle cx="515" cy="280" r="7" fill="#c34b49"/><circle cx="685" cy="280" r="7" fill="#c34b49"/><circle cx="855" cy="280" r="7" fill="#c34b49"/><circle cx="600" cy="280" r="7" fill="#24678c"/><circle cx="770" cy="280" r="7" fill="#24678c"/><text x="499" y="319" font-size="17">n</text><text x="660" y="319" font-size="17">n+1</text><text x="834" y="319" font-size="17">n+2</text><text x="570" y="260" font-size="17">n+1/2</text><text x="742" y="260" font-size="17">n+3/2</text><text x="480" y="375" font-size="17">One field updates from the circulation of the other.</text>'''+TAIL
    currents=HEAD+'''<text x="30" y="36" font-size="23">Oriented integral unknowns</text><text x="50" y="77" font-size="20">FIT: one primal face</text><rect x="100" y="130" width="225" height="210" fill="#dceaf3" stroke="#7d9eae"/><path d="M120 340 H285" fill="none" stroke="#c34b49" stroke-width="4" marker-end="url(#red)"/><path d="M325 320 V155" fill="none" stroke="#c34b49" stroke-width="4" marker-end="url(#red)"/><path d="M120 130 H285" fill="none" stroke="#c34b49" stroke-width="4" marker-end="url(#red)"/><path d="M100 320 V155" fill="none" stroke="#c34b49" stroke-width="4" marker-end="url(#red)"/><text x="180" y="368" font-size="19">+e1</text><text x="340" y="235" font-size="19">+e2</text><text x="180" y="115" font-size="19">-e3</text><text x="45" y="235" font-size="19">-e4</text><circle cx="215" cy="230" r="20" fill="white" stroke="#24678c" stroke-width="3"/><circle cx="215" cy="230" r="5" fill="#24678c"/><text x="185" y="279" font-size="18">+z flux</text><text x="480" y="77" font-size="20">MoM: RWG basis on two triangles</text><path d="M505 165 L720 130 L875 310 Z" fill="#e2edf4" stroke="#7d9eae" stroke-width="2"/><path d="M505 165 L875 310 L630 355 Z" fill="#f7e3c3" stroke="#7d9eae" stroke-width="2"/><path d="M505 165 L875 310" stroke="#a4772e" stroke-width="5"/><path d="M665 178 L700 295" stroke="#24678c" stroke-width="5" marker-end="url(#blue)"/><text x="723" y="210" font-size="21">T+</text><text x="640" y="325" font-size="21">T-</text><text x="730" y="265" font-size="18">shared edge</text><text x="495" y="395" font-size="17">Current crosses the shared edge; basis support is local.</text>'''+TAIL
    for name,value in [('yee-staggering.svg',yee),('integral-unknowns.svg',currents)]:
        (DEST/name).write_text(value,encoding='utf-8',newline='\n')


if __name__=='__main__':generate()
